#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> ages = {21, 30, 18};
    bool adults = std::all_of(ages.begin(), ages.end(), [](int age) {
        return age >= 18;
    });
    std::cout << std::boolalpha << adults;
}

#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> seats = {0, 0, 3};
    bool available = std::any_of(seats.begin(), seats.end(), [](int count) {
        return count > 0;
    });
    std::cout << std::boolalpha << available;
}
